function proposal(){return `<div class="grid wide">${panel('Proposal structure · version 2',`<div class="panel-body"><div class="eyebrow">Meridian Logistics · enterprise AI</div><h2 style="font-size:1.45rem">Operational handoff intelligence</h2><hr class="rule"><label class="field">Buyer outcome<textarea rows="3">Create visibility and accountable ownership across delayed operational handoffs, beginning with an agreed baseline workflow.</textarea></label><label class="field" style="margin-top:18px">Scope and deliverables<textarea rows="5">Discovery and baseline assessment\nAgreed data and workflow integration\nOperational intelligence workspace\nGoverned AI assistance\nActivation and value review</textarea></label><label class="field" style="margin-top:18px">Assumptions and commitments<textarea rows="4">Delivery scope is subject to technical readiness, permitted data access, and named customer owners. No performance guarantee is made before baseline agreement.</textarea></label><div class="flex" style="margin-top:18px">${btn('Save proposal version','save-proposal')}${go('Review commercial quote','quote-detail',true)}</div></div>`)}${panel('Evidence and review',`<div class="panel-body">${checks([['Buyer outcome comes from discovery',true],['Scope matches the approved offer',true],['Commercial quote linked by version',true],['Delivery owner confirms assumptions',false],['Customer acceptance not yet recorded',false]])}<hr class="rule">${listItem('Proposal owner','Arjun Rao')}${listItem('Commercial reference','Q-1042 · v'+state.quoteVersion)}${listItem('Knowledge source','Enterprise offer guide v3')}<div style="margin-top:15px">${go('Meeting evidence','meeting-detail')}</div></div>`)}</div>`;}
