function retention(){return `${stats([['Opening cohort ARR','₹80.0L','Comparable beginning-period contracts'],['Gross retention','95.0%','Excludes expansion'],['Net retention','110.0%','Includes cohort expansion'],['Cohort customers','8','Illustrative ledger example']])}<div class="grid wide">${panel('Recurring revenue reconciliation',`<div class="panel-body">${listItem('Opening recurring value','₹80.0L')}${listItem('Churn','−₹2.0L')}${listItem('Contraction','−₹2.0L')}${listItem('Expansion','+₹12.0L')}${listItem('Closing cohort recurring value','₹88.0L')}<hr class="rule"><p class="small muted">GRR = (80 − 2 − 2) / 80. NRR = (80 − 2 − 2 + 12) / 80. New customer revenue is excluded from the opening cohort calculation.</p></div>`)}${panel('Evidence requirements',`<div class="panel-body">${checks([['Comparable beginning cohort recorded',true],['Recurring and one-time lines separated',true],['Contract amendments retain effective dates',true],['Consistent period and currency basis',true]])}<hr class="rule"><h3>When evidence is missing</h3><p class="small muted" style="margin-top:8px">Display “Not yet measurable” with the missing inputs. Do not substitute 100% retention.</p><div style="margin-top:18px">${go('Renewal portfolio','renewals')}</div></div>`)}</div>`;}
function automation(){return `${stats([['Eligible actions','240','Same evaluation window'],['Completed actions','216','Observed outcomes'],['Completion rate','90.0%','216 / 240 · example'],['Human decisions','18','Authorization and exceptions']])}<div class="grid wide">${panel('Execution outcomes',`<div class="panel-body">${[['Completed',216,90,'good'],['Waiting for decision',18,7.5,'warn'],['Recoverable failure',6,2.5,'warn']].map(([n,v,p,k])=>`<div style="margin-bottom:24px"><div class="between small"><span>${n}</span><span class="num">${v} · ${p}%</span></div><div class="progress ${k}" style="margin-top:9px"><i style="width:${p}%"></i></div></div>`).join('')}<p class="small muted">Counts represent action requests and outcomes in one window, not AI activity log volume.</p></div>`)}${panel('Reliability and operating cost',`<div class="panel-body">${listItem('Oldest pending action','12 min')}${listItem('Provider reconciliation','1 item')}${listItem('Terminal failures','0 in example window')}${listItem('Observed duplicate effects','0 in example fixtures')}${listItem('AI and provider cost','₹2,840 · example period')}${listItem('Cost per qualified opportunity','₹284 · example')}<hr class="rule">${go('Inspect workflow executions','runs')}</div>`)}</div>`;}
function intelligence(){return `<div class="grid wide">${panel('Contextual research',`<div class="panel-body"><label class="field">Business context<select><option>Meridian · enterprise AI opportunity</option><option>Cedar · customer success</option><option>Enterprise AI campaign</option></select></label><label class="field" style="margin-top:18px">Question<textarea id="research-question">What evidence is missing before the Meridian proposal can progress?</textarea></label><div style="margin-top:18px">${btn('Ask grounded copilot','research',true)}</div><div id="research-answer" class="section-gap">${state.copilotAnswer?copilotAnswer():''}</div></div>`)}${panel('Approved context sources',`<div class="panel-body">${listItem('Discovery outcome','Verified buyer criteria')}${listItem('Quote policy','Version 2 · discount boundary')}${listItem('Product knowledge','Enterprise offer guide v3')}${listItem('Delivery readiness','Owner confirmation pending')}<hr class="rule"><p class="small muted">Recommendations expose sources and missing evidence. They do not authorize commercial commitments or external actions.</p></div>`)}</div>`;}
