function company(){return `<div class="grid wide">${panel('Workspace identity',`<div class="panel-body"><div class="form-grid"><label class="field">Workspace name<input value="AGRAYIAN AI LABS"></label><label class="field">Product name<input value="Sales Engine"></label><label class="field">Operating timezone<select><option>Asia/Kolkata · IST</option><option>UTC</option></select></label><label class="field">Reporting currency<select><option>INR · Indian rupee</option><option>USD · US dollar</option></select></label><label class="field">Default territory<input value="India · enterprise"></label><label class="field">Workspace owner<input value="Maya Kapoor"></label></div><hr class="rule"><label class="field">Approved offer summary<textarea>Governed AI implementation and managed services for enterprise operations, with agreed outcomes and accountable delivery.</textarea></label><div class="sticky-action">${btn('Save workspace','save-workspace',true)}</div></div>`)}${panel('Workspace administration',`<div class="panel-body settings-menu">${[['setup','Revenue launch','Configure the first operating strategy.'],['integrations','Connections','Tenant-owned channels and sources.'],['users','People & access','Roles and account lifecycle.'],['security','Security & data','Identity and data controls.'],['knowledge','Knowledge','Approved claims and policy sources.'],['pilot','Readiness','Observed verification evidence.']].map(([id,title,desc])=>`<a class="setting-card" href="#/${id}">${icon(SCREEN[id].workspace==='settings'?'settings':'document')}<div><h3>${title}</h3><p>${desc}</p></div></a>`).join('')}</div>`)}</div>`;}
const SETUP=[['Company & offer','Confirm what the company sells and which claims are approved.'],['Objective & audience','Set the revenue goal, ICP, territory, and campaign focus.'],['Channels & ownership','Map providers, sources, teams, and accountable handoffs.'],['Policies & limits','Set eligibility, action caps, budget, and authorization grants.'],['Dry run & launch','Inspect the expected journey and activate a limited scope.']];
function setup(){const i=state.setupStep;let content=i===0?`<div class="form-grid"><label class="field">Company<input value="AGRAYIAN AI LABS"></label><label class="field">Primary offer<input value="Enterprise AI transformation"></label></div><label class="field" style="margin-top:18px">Offer scope<textarea>Discovery, implementation, governed AI assistance, and accountable activation.</textarea></label>`:i===1?`<div class="form-grid"><label class="field">Quarter target<input value="₹60.0L accepted business"></label><label class="field">Audience<select><option>Enterprise AI buyers</option><option>Healthcare operations</option></select></label><label class="field">Territory<input value="India"></label><label class="field">Campaign budget ceiling<input value="₹2.50L monthly"></label></div>`:i===2?`<div class="form-grid"><label class="field">Inbound response channel<select><option>Email · demo connection</option></select></label><label class="field">Meeting calendar<select><option>Account owner calendar</option></select></label><label class="field">Lead routing<select><option>Enterprise Sales · territory rules</option></select></label><label class="field">Customer handoff<select><option>Customer Operations</option></select></label></div>`:i===3?`<div class="form-grid"><label class="field">Autonomy mode<select><option>Bounded autopilot</option><option>Assisted</option><option>Observe</option></select></label><label class="field">Daily contact limit<input type="number" min="1" value="50"></label></div>${checks([['Current contact eligibility required',true],['Approved template and campaign version bound',true],['Discounts above 5% require manager review',true],['Every channel obeys emergency pause',true]])}`:`${notice('<strong>Dry run ready</strong><p>The example journey identifies its guards, owner handoffs, and externally visible actions before activation.</p>','good')}${checks([['Capture and duplicate resolution',true],['Fit and eligibility evaluation',true],['Owner and activated journey routing',true],['Version-bound authorization',true],['Reply, meeting, and commercial handoffs',true]])}<div style="margin-top:18px">${go('Inspect planned execution','run-detail')}</div>`;return `<div class="grid wide">${panel('Revenue launch · '+SETUP[i][0],`<div class="panel-body"><div class="phase-nav">${SETUP.map(([n],j)=>`<span class="${j===i?'active':''}">${j+1} · ${n}</span>`).join('')}</div><h2>${SETUP[i][0]}</h2><p class="muted small" style="margin:8px 0 22px">${SETUP[i][1]}</p>${content}<div class="sticky-action">${i>0?btn('Back','setup-back'):''}${btn(i===4?'Activate demo journey':'Continue','setup-next',true)}</div></div>`)}${panel('Activation checklist',steps(SETUP,i))}</div>`;}
function integrations(){return `${notice('<strong>Capabilities and readiness are separate</strong><p>A connection must expose tenant ownership, required scope, freshness, and tested actions. These connection states are illustrative.</p>')}<div class="grid three">${[['Gmail','Email send, read, and replies','Connected','Tenant OAuth · current','mail'],['Google Calendar','Availability, booking, changes','Connected','Owner calendar mapped','calendar'],['LinkedIn Ads','Campaign, creative, spend','Review required','Account and budget grant needed','megaphone'],['Meta distribution','Facebook and Instagram','Not connected','Publishing and ads are separate scopes','megaphone'],['Discovery source','Account and contact finding','Connected','Source does not establish outreach eligibility','search'],['Voice provider','Calls and human escalation','Not ready','Recipient scope and sandbox test needed','phone'],['Customer usage','Activation and health evidence','Connected','Fresh production signal mapping','chart'],['Support signals','Incidents and recovery context','Connected','Signed events · account mapping','heart'],['Billing signals','Contract and payment evidence','Not connected','Customer and invoice mapping','document']].map(([name,desc,status,note,ic])=>`<section class="panel workspace-card"><div class="between"><span class="avatar square">${icon(ic)}</span>${badge(status)}</div><h2>${name}</h2><p>${desc}</p><span class="small muted">${note}</span>${btn(status==='Connected'?'Inspect connection':'Configure connection','connection:'+name)}</section>`).join('')}</div>`;}
function models(){return `${panel('Model and decision registry',`<div class="table-wrap"><table><thead><tr><th>Capability</th><th>Method</th><th>Purpose</th><th>Readiness</th><th>Human boundary</th></tr></thead><tbody>${[['Content drafting','Grounded language model','Approved offer assets','Configured','Claims and publication review'],['Lead fit assessment','Deterministic rules','Evidence-based qualification','Active','Ambiguous facts'],['Forecast probability','Explicit stage rules','Period-weighted pipeline','Active','Owner forecast review'],['Learned propensity','Training-data collection','Future ranking improvement','Data collection','No trained-model claim'],['Reply classification','Structured AI + validation','Route conversation intent','Configured','Sensitive or ambiguous reply']].map(r=>`<tr>${r.map((v,i)=>`<td>${i===3?badge(v):h(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}<div class="grid section-gap">${panel('AI operating boundaries',`<div class="panel-body">${checks([['Structured outputs validated by application logic',true],['Knowledge version retained with recommendations',true],['Money, recipients, and permission checked deterministically',true],['External action authorization is separate',true]])}</div>`)}${panel('Evaluation evidence',`<div class="panel-body">${listItem('Draft factuality','Source-grounding checks required')}${listItem('Reply routing','Labeled evaluation dataset required')}${listItem('Learned model activation','Holdout evaluation and approval required')}<hr class="rule"><p class="small muted">A configured model is not automatically a validated business capability.</p></div>`)}</div>`;}
function flags(){return `<div class="grid wide">${panel('Release and feature controls',`<div class="panel-body">${[['Market intelligence workspace',true,'Show the evidence and account research surfaces.'],['Campaign planning preview',true,'Preview objective-linked marketing workflows.'],['Proposal preparation',true,'Enable versioned proposal editing.'],['Customer recovery plans',true,'Enable evidence-backed success workflows.'],['Learned model ranking',false,'Requires a validated production model.'],['Voice execution',false,'Requires provider and eligibility verification.']].map(([n,on,d])=>`<div class="switch"><div>${n}<p>${d}</p></div><input type="checkbox" ${on?'checked':''} aria-label="${n}"></div>`).join('')}<div class="sticky-action">${btn('Save release controls','save-flags',true)}</div></div>`)}${panel('Control scope',`<div class="panel-body"><p class="muted">Feature controls determine product availability. They do not grant permission to contact people, spend money, or commit commercial terms.</p><hr class="rule">${listItem('Business authorization','Autonomy policy grants')}${listItem('Role access','People and permissions')}${listItem('Connection readiness','Provider capability checks')}${listItem('Execution suspension','Workspace and channel pauses')}<div style="margin-top:18px">${go('Inspect policies','policies')}</div></div>`)}</div>`;}
function pilot(){return `${notice('<strong>Readiness is evidence-backed</strong><p>These are example readiness states for the design. The earlier repository audit remains the authority on actual validation results.</p>','warn')}<div class="grid wide">${panel('Activation readiness',`<div class="row"><div class="main"><h3>Tenant isolation</h3><p>PostgreSQL role and row-level-security test results.</p></div>${badge('Verification required')}</div><div class="row"><div class="main"><h3>Event recovery and concurrency</h3><p>Duplicate delivery, worker restart, and replay invariants.</p></div>${badge('Verification required')}</div><div class="row"><div class="main"><h3>Provider sandbox execution</h3><p>Delivery result, unknown-outcome reconciliation, and channel stops.</p></div>${badge('Verification required')}</div><div class="row"><div class="main"><h3>Backup restore</h3><p>Observed successful restore with current operating procedure.</p></div>${badge('Evidence needed')}</div><div class="row"><div class="main"><h3>Policy and ownership</h3><p>Approved segment, authorization limits, and escalation owners.</p></div>${badge('Prepared','info')}</div>`)}${panel('Limited launch scope',`<div class="panel-body">${listItem('Initial journey','Eligible inbound qualification')}${listItem('Contact ceiling','50 / day after authorization')}${listItem('Operator','Revenue Operations')}${listItem('Initial mode','Assisted until gates verified')}${listItem('Expansion criteria','Stable delivery and recovered failures')}<hr class="rule">${go('Revenue launch setup','setup')}${go('Inspect policies','policies')}</div>`)}</div>`;}
function security(){return `<div class="grid">${panel('Identity and access',`<div class="panel-body">${['Require MFA for administrators','Use SSO for enterprise members','Revoke sessions on deactivation','Restrict commercial approval by role'].map((n,i)=>`<div class="switch"><div>${n}<p>${i===1?'Identity integration requires production implementation.':'Applies to the configured account scope.'}</p></div><input type="checkbox" ${i!==1?'checked':''} aria-label="${n}"></div>`).join('')}<hr class="rule">${go('People and access','users')}</div>`)}${panel('Data lifecycle',`<div class="panel-body"><label class="field">Activity retention<select><option>365 days</option><option>180 days</option><option>Custom policy</option></select></label><label class="field" style="margin-top:18px">Audit retention<select><option>Workspace policy · requires review</option></select></label><hr class="rule">${listItem('Customer export','Role-controlled request')}${listItem('Deletion request','Policy and dependency review')}${listItem('Credential access','Tenant-bound connections')}${listItem('Restore verification','Observed test evidence required')}<div style="margin-top:18px">${btn('Save security preferences','save-security',true)}</div></div>`)}</div>`;}
function designSystem(){return `<div class="grid wide">${panel('Midnight workspace · foundations',`<div class="panel-body"><h3>Color roles</h3><div class="grid three" style="margin-top:15px">${[['Canvas','#0D1118'],['Sidebar','#10151E'],['Surface','#151C27'],['Raised','#1B2432'],['Border','#293346'],['Action','#99A5FF']].map(([n,c])=>`<div><div style="height:45px;border:1px solid var(--line);border-radius:5px;background:${c}"></div><div class="small" style="margin-top:8px">${n}</div><div class="small muted">${c}</div></div>`).join('')}</div><hr class="rule"><h3>Typography and density</h3><p class="muted small" style="margin-top:10px">Inter · 16px body · 14px controls and tables · 12–13px metadata · 28–30px page titles. Eight-pixel spacing rhythm with compact, readable operational surfaces.</p><hr class="rule"><div class="flex">${btn('Primary action','design-action',true)}${btn('Secondary action','design-action')}${btn('Disabled action','design-action',false,'disabled')}</div><div class="flex" style="margin-top:18px">${badge('Approved')}${badge('Needs review')}${badge('Blocked')}${badge('Scheduled')}${badge('Draft')}</div></div>`)}${panel('Component and state library',`<div class="panel-body"><label class="field">State to inspect<select id="design-state"><option value="empty">Empty</option><option value="loading">Loading</option><option value="error">Recoverable failure</option><option value="success">Completed</option></select></label><div id="design-state-preview" style="margin-top:20px">${statePreview('empty')}</div><hr class="rule">${checks([['Keyboard-visible focus',true],['State labels accompany color',true],['Native dialog and semantic tables',true],['Mobile navigation and wrapped actions',true],['Destructive controls require confirmation',true],['Reduced motion respected',true]])}</div>`)}</div>`;}
function statePreview(which){return which==='empty'?`<div class="empty"><h3>No workflows activated</h3><p>Prepare a journey, validate its guards, and authorize its scope.</p>${go('Open playbooks','playbooks')}</div>`:which==='loading'?`<div role="status" aria-label="Loading evidence"><div class="loading-line wide"></div><div class="loading-line"></div><div class="loading-line short"></div><span class="small muted">Loading source evidence…</span></div>`:which==='error'?notice('<strong>Provider result not confirmed</strong><p>Reconcile the external result before repeating the action.</p><div style="margin-top:12px">'+btn('Inspect recovery','recover')+'</div>','warn'):notice('<strong>Action completed</strong><p>Provider result observed, audit updated, next eligible step scheduled.</p>','good');}
function screenIndex(){return `${stats([['Designed screens',String(SCREENS.length),'All accessible from this index'],['Original page coverage',String(SCREENS.filter(s=>s.original).length),'Repository route templates'],['Revenue workspaces','8','Plus workspace settings'],['Journey additions',String(SCREENS.filter(s=>!s.original).length),'Handoffs and authoring screens']])}${panel('Page design directory',`<div class="toolbar"><input data-table-search placeholder="Search pages, workspace, or original route" aria-label="Search page designs"><select data-table-filter aria-label="Filter page origin"><option value="">All pages</option><option value="existing">Existing page</option><option value="added">Added workflow screen</option></select></div><div class="table-wrap"><table><thead><tr><th>Page design</th><th>Workspace</th><th>Original route</th><th>Next handoff</th></tr></thead><tbody>${SCREENS.map(s=>`<tr data-search="${h([s.title,s.workspace,s.original,s.original?'existing':'added'].join(' ').toLowerCase())}"><td><a class="record-link" href="#/${s.id}">${h(s.title)}</a></td><td>${h(WORKSPACES.find(w=>w.id===s.workspace).name)}</td><td><span class="small muted">${h(s.original||'Added workflow screen')}</span></td><td><a href="#/${s.next}" class="small">${h(SCREEN[s.next].title)}</a></td></tr>`).join('')}</tbody></table></div><div class="empty" id="no-results" hidden><h3>No matching page designs</h3><p>Try another page or workspace.</p></div>`,badge('Complete page map','purple'))}`;}
function comingSoon(){return `${panel('Capability availability',`<div class="panel-body"><h2>Designed journeys and operating capabilities</h2><p class="muted" style="margin:12px 0 22px">A visible interface is not proof that a provider, trained model, or automated handoff is production-ready. Inspect the capability and its verification evidence before enabling it.</p><div class="table-wrap"><table><thead><tr><th>Capability</th><th>Design coverage</th><th>Operational verification</th></tr></thead><tbody><tr><td>Connected revenue journey</td><td>${badge('Designed','purple')}</td><td>Implementation backlog in audit</td></tr><tr><td>Live market intelligence</td><td>${badge('Designed','purple')}</td><td>Provider work required</td></tr><tr><td>Learned ranking</td><td>Governance interface</td><td>${badge('Data collection')}</td></tr><tr><td>Voice channel</td><td>Script and readiness interface</td><td>${badge('Verification required')}</td></tr></tbody></table></div><div class="flex" style="margin-top:20px">${go('All page designs','screen-index',true)}${go('Connections','integrations')}</div></div>`)}`;}
function login(){return `<main class="auth"><section class="auth-story"><a href="#/home" class="brand"><span class="brand-mark"><i></i><i></i><i></i></span>Sales Engine</a><div><div class="eyebrow">AGRAYIAN AI LABS</div><h1>A connected workspace for the revenue team.</h1><p>Strategy, demand, sales execution, commercial closure, and customer value—connected through accountable journeys.</p><div class="flex" style="margin-top:30px">${badge('Governed execution','purple')}${badge('Evidence-backed decisions','info')}</div></div><p class="small muted">Design prototype · fictional records · no live operations</p></section><section class="auth-form"><form class="auth-box" id="login-form"><div><h1>Welcome back</h1><p class="muted" style="margin-top:10px">Sign in to your revenue workspace.</p></div><label class="field">Work email<input type="email" autocomplete="username" value="maya@example.com" required></label><label class="field">Password<input type="password" autocomplete="current-password" value="demoprototype" required></label><button type="submit" class="btn primary">Enter demo workspace</button>${btn('Preview enterprise SSO','sso')}<div class="small muted">This screen demonstrates the sign-in experience. It does not authenticate against your repository.</div>${go('Browse all page designs','screen-index')}</form></section></main>`;}
function capture(){return `<main class="capture-page"><section class="panel capture-card"><div class="public-brand"><span class="brand-mark"><i></i><i></i><i></i></span>AGRAYIAN AI LABS</div><div class="eyebrow">Enterprise AI discovery</div><h1>Discuss your operational workflow</h1><p class="muted" style="margin:15px 0 26px">Share the process you want to improve. Our discovery discussion establishes the requirements, owners, and evidence of success.</p><form id="capture-form" class="stack"><div class="form-grid"><label class="field">Full name<input required value="Lina Shah" autocomplete="name"></label><label class="field">Work email<input required type="email" value="lina@example.com" autocomplete="email"></label><label class="field">Company<input required value="Meridian Logistics" autocomplete="organization"></label><label class="field">Role<input value="Director of Operations" autocomplete="organization-title"></label></div><label class="field">Which workflow is the priority?<textarea required>Visibility and accountable ownership at delayed operations handoffs.</textarea></label><label class="flex small muted"><input class="checkbox" type="checkbox" required checked>I agree to be contacted about this discovery request.</label><button class="btn primary" type="submit">Submit example request</button></form><p class="small muted" style="margin-top:20px">Design preview. No request or personal information is sent externally.</p><div style="margin-top:15px">${go('See the inbound handoff','acquisition')}</div></section></main>`;}
const VIEWS={home,flow,strategy,market,'market-detail':marketDetail,'campaign-detail':campaignDetail,content,'content-editor':contentEditor,calendar,acquisition,'lead-detail':leadDetail,'account-detail':accountDetail,'contact-detail':contactDetail,imports,'sequence-builder':sequenceBuilder,conversations,'meeting-detail':meetingDetail,voice,pipeline,'opportunity-detail':opportunityDetail,'task-detail':taskDetail,commercial,'quote-detail':quoteDetail,proposal,'contract-detail':contractDetail,'customer-detail':customerDetail,onboarding,success,'renewal-detail':renewalDetail,runs,'run-detail':runDetail,approvals,'playbook-builder':playbookBuilder,policies,forecast,retention,automation,intelligence,company,setup,integrations,models,flags,pilot,security,'design-system':designSystem,'screen-index':screenIndex,'coming-soon':comingSoon,login,capture};
let current='home';let toastTimer;
function toast(message){const node=document.getElementById('toast');node.textContent=message;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),4200);}
function navigate(id){location.hash='/'+id;}
function render(){const raw=decodeURIComponent(location.hash.replace(/^#\/?/,''));current=SCREEN[raw]?raw:'home';const s=SCREEN[current];document.title=s.title+' · Sales Engine';const body=s.view==='table'?renderTable(s):(VIEWS[s.view]?VIEWS[s.view]():emptyView('Design not available','This page needs a layout.'));document.getElementById('app').innerHTML=['login','capture'].includes(s.id)?body:shell(s,body);bindPage();}
function bindPage(){document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action)));const role=document.getElementById('role');if(role)role.addEventListener('change',()=>{state.role=role.value;render();toast('Role workspace changed. Access rules are illustrative.');});const search=document.querySelector('[data-table-search]'),filter=document.querySelector('[data-table-filter]');const filterTable=()=>{const q=(search?.value||'').toLowerCase(),f=(filter?.value||'').toLowerCase();let visible=0;document.querySelectorAll('tbody tr[data-search]').forEach(r=>{const yes=r.dataset.search.includes(q)&&(!f||r.dataset.search.includes(f));r.hidden=!yes;if(yes)visible++;});const no=document.getElementById('no-results');if(no)no.hidden=visible>0;};search?.addEventListener('input',filterTable);filter?.addEventListener('change',filterTable);document.getElementById('design-state')?.addEventListener('change',e=>document.getElementById('design-state-preview').innerHTML=statePreview(e.target.value));document.getElementById('login-form')?.addEventListener('submit',e=>{e.preventDefault();navigate('home');toast('Demo workspace opened.');});document.getElementById('capture-form')?.addEventListener('submit',e=>{e.preventDefault();navigate('lead-detail');toast('Example request captured. Qualification and routing are shown in the lead journey.');});}
function modal(title,body,buttons=''){const d=document.getElementById('modal');d.innerHTML=`<header class="modal-head"><h2 id="modal-title">${h(title)}</h2><button class="btn iconbtn" data-modal-close aria-label="Close dialog">${icon('x')}</button></header><div class="modal-body">${body}</div>${buttons?`<footer class="modal-foot">${buttons}</footer>`:''}`;d.querySelector('[data-modal-close]').addEventListener('click',()=>d.close());d.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action)));if(!d.open)d.showModal();return d;}
function closeModal(){document.getElementById('modal').close();}
function searchDialog(){const d=modal('Find a page or record',`<label class="field">Search the complete product<input id="command-search" placeholder="Try quotes, customer, policy, or lead" autofocus></label><div class="command-results" id="command-results"></div>`);const input=d.querySelector('#command-search');const results=d.querySelector('#command-results');const update=()=>{const q=input.value.toLowerCase();results.innerHTML=SCREENS.filter(s=>[s.title,s.workspace,s.original].join(' ').toLowerCase().includes(q)).slice(0,18).map(s=>`<a href="#/${s.id}">${icon(WORKSPACES.find(w=>w.id===s.workspace).icon)}${h(s.title)}<small>${h(WORKSPACES.find(w=>w.id===s.workspace).name)}</small></a>`).join('')||'<div class="empty">No matching pages.</div>';results.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeModal));};input.addEventListener('input',update);update();setTimeout(()=>input.focus(),20);}
function formDialog(title,fields,onSave){const id='save-'+Date.now();const d=modal(title,`<form id="${id}"><div class="form-grid">${fields.map(([label,value,type='text'])=>`<label class="field">${h(label)}<input name="${h(label)}" type="${type}" value="${h(value)}" required></label>`).join('')}</div></form>`,btn('Cancel','close')+`<button type="submit" form="${id}" class="btn primary">Save example</button>`);d.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));onSave(values);closeModal();render();});}
function newRecord(){const s=SCREEN[current];if(TABLES[current]){const c=TABLES[current];formDialog(s.action,[[c.columns[0].split('/')[0],'New example record'],['Owner','Maya Kapoor']],values=>{const row=c.columns.map((col,i)=>i===0?values[c.columns[0].split('/')[0]]+'|Created in this prototype':/owner|manager|actor/i.test(col)?values.Owner:/status|state|readiness/i.test(col)?'Draft':'To review');(state.newRows[current]??=[]).push(row);toast('Example record added. Activation still requires the relevant workflow checks.');});}else formDialog(s.action,[['Name','New example'],['Accountable owner','Maya Kapoor']],()=>toast('Example saved for design review.'));}
function act(action){const [kind,...parts]=action.split(':');const value=parts.join(':');
 if(kind==='primary'){const id=value;const mappings={home:'approvals',flow:'run-detail',strategy:'edit-strategy',market:'signals','market-detail':'campaign-detail','campaign-detail':'launch-review',content:'content-brief','content-editor':'schedule',calendar:'schedule',acquisition:'capture',leads:'create','lead-detail':'conversations','account-detail':'opportunity-detail','contact-detail':'lead-detail',imports:'file-input',sequences:'sequence-builder','sequence-builder':'validate-sequence',conversations:'review-reply','meeting-detail':'meeting-outcome',voice:'voice-review',pipeline:'opportunity-detail','opportunity-detail':'quote-detail',deals:'opportunity-detail','task-detail':'complete-task',commercial:'quote-detail','quote-detail':'quote-request',proposal:'quote-detail','contract-detail':'contract-handoff',onboarding:'milestone:0',success:'customer-detail','renewal-detail':'value-review',runs:'run-detail','run-detail':'continue-journey',approvals:'quote-detail',playbooks:'playbook-builder','playbook-builder':'validate-playbook',policies:'save-policy',forecast:'pipeline',retention:'renewals',automation:'runs',intelligence:'research',company:'save-workspace',setup:'setup-next',models:'model-review',flags:'save-flags',pilot:'pilot-review',security:'save-security','design-system':'screen-index','coming-soon':'integrations'};const target=mappings[id];if(target&&SCREEN[target])navigate(target);else if(target)act(target);else newRecord();return;}
 if(kind==='close'){closeModal();return;}
 if(kind==='menu'){document.getElementById('sidebar')?.classList.toggle('open');return;}
 if(kind==='search'){searchDialog();return;}
 if(kind==='notifications'){navigate('approvals');return;}
 if(kind==='copilot'){modal('Copilot · '+SCREEN[current].title,copilotAnswer()+`<p class="small muted">Contextual advice exposes source records and missing evidence. It does not execute external actions.</p>`);return;}
 if(kind==='pause'){modal(state.paused?'Resume revenue journeys':'Pause revenue journeys',`<p>${state.paused?'Resume eligible example work within the current operating policies.':'Suspend every example execution channel. Completed work and queued decisions remain visible.'}</p>`,btn('Cancel','close')+btn(state.paused?'Resume journeys':'Confirm pause','confirm-pause',true));return;}
 if(kind==='confirm-pause'){state.paused=!state.paused;closeModal();render();toast(state.paused?'All example journeys paused.':'Example journeys resumed within their boundaries.');return;}
 if(kind==='decision-tab'){state.decisionTab=value;render();return;}
 if(kind==='mode'){state.policyMode=value;render();return;}
 if(kind==='create'){newRecord();return;}
 if(kind==='approve-quote'){state.quoteApproval='approved';render();toast('Quote version '+state.quoteVersion+' authorized. Delivery has not happened.');return;}
 if(kind==='decline-quote'){state.quoteApproval='declined';state.quoteSent=false;render();toast('Quote authorization declined. No delivery is permitted.');return;}
 if(kind==='edit-quote'){state.quoteVersion++;state.quoteApproval='pending';state.quoteSent=false;state.accepted=false;render();toast('New quote version created. Previous authorization is invalidated.');return;}
 if(kind==='quote-request'){navigate('approvals');toast('Decision is bound to quote version '+state.quoteVersion+'.');return;}
 if(kind==='send-quote'){if(state.paused){toast('Workspace paused. No example delivery occurs.');return;}if(state.quoteApproval!=='approved'){toast('This quote version requires authorization first.');return;}state.quoteSent=true;render();toast('Example delivery result recorded separately from authorization.');return;}
 if(kind==='accept-quote'){if(!state.quoteSent){toast('Delivery and buyer acceptance evidence are required.');return;}state.accepted=true;state.journeyStep=7;render();toast('Example buyer acceptance recorded. Contract handoff is ready.');return;}
 if(kind==='contract-handoff'){if(!state.accepted){toast('Buyer acceptance is required before handoff.');return;}navigate('onboarding');toast('Customer onboarding handoff opened with accepted scope.');return;}
 if(kind==='meeting-outcome'){const outcome=document.getElementById('meeting-qualified')?.value||'Qualified opportunity';if(outcome!=='Qualified opportunity'){toast('Outcome retained. Opportunity handoff deferred pending qualification.');return;}state.meetingOutcome=true;state.journeyStep=Math.max(state.journeyStep,5);navigate('opportunity-detail');toast('Verified qualification retained. Opportunity handoff opened.');return;}
 if(kind==='complete-task'){state.tasksDone=true;render();toast('Completion evidence recorded. Linked work can resume.');return;}
 if(kind==='milestone'){const n=Number(value);if(n!==state.onboardingDone){toast('Complete the preceding milestone first.');return;}state.onboardingDone=Math.min(4,n+1);render();toast('Example milestone evidence recorded.');return;}
 if(kind==='continue-journey'){if(state.paused){toast('Resume the workspace before continuing.');return;}if(state.journeyStep===4&&!state.meetingOutcome){navigate('meeting-detail');toast('Record the qualification outcome before opportunity handoff.');return;}if(state.journeyStep===6&&!state.accepted){navigate('quote-detail');toast('Authorize, deliver, and record acceptance before customer handoff.');return;}state.journeyStep=Math.min(8,state.journeyStep+1);render();toast('Example progressed with earlier completed steps retained.');return;}
 if(kind==='setup-back'){state.setupStep=Math.max(0,state.setupStep-1);render();return;}
 if(kind==='setup-next'){if(state.setupStep<4){state.setupStep++;render();}else{navigate('run-detail');toast('Limited example journey activated. No live provider is connected.');}return;}
 if(kind==='schedule'){if(state.paused){toast('Workspace paused. Scheduling does not progress.');return;}modal('Schedule approved asset',`<div class="form-grid"><label class="field">Date<input type="date" value="2026-10-05"></label><label class="field">Time · IST<input type="time" value="14:30"></label></div><p class="small muted">Approval is bound to asset v2 and campaign plan v3. This prototype records an example schedule only.</p>`,btn('Cancel','close')+btn('Confirm example schedule','confirm-schedule',true));return;}
 if(kind==='confirm-schedule'){state.contentScheduled=true;closeModal();navigate('calendar');toast('Example asset scheduled. Publication remains a separate outcome.');return;}
 if(kind==='validate-import'){const f=document.getElementById('csv-file')?.files?.[0];if(!f){toast('Select a CSV file to preview the validation handoff.');return;}document.getElementById('import-result').innerHTML=notice('<strong>File selected: '+h(f.name)+'</strong><p>This prototype demonstrates the validation result interface. It does not upload or parse your records.</p>','good');return;}
 if(kind==='file-input'){document.getElementById('csv-file')?.click();return;}
 if(kind==='download-template'){const blob=new Blob(['name,email,company,source,eligibility_evidence\nExample Contact,contact@example.com,Example Company,inbound,requested offer follow-up\n'],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sales-engine-import-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);return;}
 if(kind==='research'){state.copilotAnswer=true;const answer=document.getElementById('research-answer');if(answer)answer.innerHTML=copilotAnswer();else navigate('intelligence');return;}
 if(kind==='recover'){modal('Recover without repeating completed effects',`${checks([['Inspect the last provider result and action key',true],['Reconcile unknown external outcome before retry',true],['Revalidate eligibility and authorization',true],['Resume from the failed step',true]])}<p class="small muted">Recovery is an explicit state with an owner and retry budget. Failed events do not disappear as completed work.</p>`,go('Execution centre','runs')+btn('Close','close'));return;}
 if(kind==='customer-message'){modal('Customer communication · Cedar Health',`<div class="callout"><div>Recipient: Neha Iyer · verified relationship contact<br>Context: activation milestone and open dependency</div></div><label class="field">Message<textarea>We have prepared an update on the activation milestone and the remaining integration dependency. Let us confirm the accountable owner and next evidence of progress in the value review.</textarea></label><p class="small muted">The design separates message authorization from deferred, delivered, and failed outcomes.</p>`,btn('Close','close')+btn('Authorize example message','authorize-customer',true));return;}
 if(kind==='authorize-customer'){if(state.paused){toast('Workspace paused. No example dispatch occurs.');return;}closeModal();toast('Example message authorized. A delivery result would be tracked separately.');return;}
 if(kind==='connection'){modal(value+' · connection setup',`<p>Tenant ownership, channel scope, readiness checks, and token health are shown together.</p><div class="form-grid"><label class="field">Connection name<input value="${h(value)} · workspace"></label><label class="field">Owner<input value="Revenue Operations"></label></div>${checks([['Tenant-owned credentials',true],['Required scopes disclosed',true],['Sandbox verification before activation',false]])}<p class="small muted">No authorization request or provider connection is initiated by this prototype.</p>`,btn('Close','close')+btn('Save example configuration','connection-save',true));return;}
 if(kind==='connection-save'){closeModal();toast('Example connection configuration saved. Verification is still required.');return;}
 if(kind==='sso'){modal('Enterprise sign-in',`<p>The production implementation connects the selected identity provider, enforces workspace policy, and applies role and session rules.</p><label class="field">Workspace domain<input value="example.com"></label><p class="small muted">This is a design preview and does not start authentication.</p>`,btn('Close','close'));return;}
 if(kind==='edit-strategy'){formDialog('Edit revenue strategy',[['Quarter target','₹60.0L'],['Territory','India · enterprise'],['Accountable owner','Maya Kapoor']],()=>toast('Example strategy version saved. Review its authorization boundaries.'));return;}
 if(kind==='content-brief'){formDialog('Campaign content brief',[['Campaign','Enterprise AI transformation'],['Asset','LinkedIn insight'],['Reviewer','Maya Kapoor']],()=>{navigate('content-editor');toast('Example brief opened in the content editor.');});return;}
 if(kind==='launch-review'){modal('Campaign launch review',`${checks([['Audience and offer bound to plan v3',true],['Approved assets and capture source ready',true],['Budget and channel grant current',true],['New asset version still requires review',false]])}<p class="small muted">Changes outside the grant remain in the decision inbox.</p>`,go('Review assets','content')+btn('Close','close'));return;}
 if(kind==='review-reply'){modal('Review conversation response',`<p>Confirm the meeting context, recipient, and active conversation before delivery.</p><label class="field">Draft<textarea>${h(document.getElementById('reply-draft')?.value||'Thanks for the discovery request. We have prepared the next discussion.')}</textarea></label><p class="small muted">Competing follow-ups are suspended. Authorization and delivery remain separate.</p>`,btn('Close','close')+btn('Authorize example response','authorize-reply',true));return;}
 if(kind==='authorize-reply'){if(state.paused){toast('Workspace paused. No example dispatch occurs.');return;}closeModal();toast('Example response authorized. No email was sent.');return;}
 if(kind==='voice-review'){modal('Voice authorization is incomplete',`${checks([['Approved script and escalation path',true],['Verified recipient voice scope',false],['Provider sandbox result',false]])}<p class="small muted">Live dialing stays unavailable until the evidence and channel are ready.</p>`,go('View connections','integrations')+btn('Close','close'));return;}
 if(kind==='validate-sequence'||kind==='validate-playbook'||kind==='dry-run'){modal(kind==='dry-run'?'Journey dry run':'Definition validation',`${checks([['Every step uses a supported executor',true],['Eligibility and suppression guards defined',true],['Reply and pause transitions configured',true],['Owner and escalation specified',true],['Version-bound grant required before activation',true]])}<p class="small muted">This demonstrates validation and dry-run UX. Production execution requires the implementation described in the audit.</p>`,go('Inspect run','run-detail')+btn('Close','close'));return;}
 if(kind==='add-sequence-step'){formDialog('Add sequence step',[['Step type','Wait for evidence'],['Owner','Account owner']],()=>toast('Example step prepared. Validate its executor and guards before activation.'));return;}
 if(kind==='value-review'){modal('Cedar · value review preparation',`<label class="field">Observed outcome summary<textarea>Activation is progressing, with one open integration dependency. Confirm first workflow value before proposing renewal or expansion terms.</textarea></label>${checks([['Current usage and support evidence attached',true],['Sponsor and review owner mapped',true],['Unverified value claims excluded',true]])}`,btn('Close','close')+btn('Save example review','save-value-review',true));return;}
 if(kind==='model-review'||kind==='pilot-review'||kind==='evidence'){modal(kind==='evidence'?'Contact eligibility evidence':'Verification evidence',`<p>Inspect the approved source, current version, freshness, accountable owner, and observed verification result.</p><p class="small muted">Missing verification remains visible and blocks dependent activation. The design does not claim that the earlier repository defects have been fixed.</p>`,go('Readiness workspace','pilot')+btn('Close','close'));return;}
 if(kind==='design-action'){toast('Component interaction preview.');return;}
 if(kind.startsWith('save')||kind==='asset-review'){if(document.getElementById('modal').open)closeModal();toast(kind==='save-policy'?'Example policy saved. It applies only to its scoped grant.':kind==='asset-review'?'Example asset review requested. Publication is not yet authorized.':'Example change recorded for design review.');return;}
 toast('This action is available as a design preview.');
}
window.addEventListener('hashchange',()=>{if(document.getElementById('modal').open)closeModal();render();window.scrollTo({top:0,behavior:'instant'});});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog();}});
document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();
// Structured access uses the same local, illustrative state as the visible prototype.
(()=>{const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'list_design_screens',title:'List all page designs',description:'Read the screen catalog of this UI/UX prototype. All records and metrics are illustrative.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return {screens:SCREENS.map(s=>({id:s.id,title:s.title,workspace:s.workspace,originalRoute:s.original})),prototype:true};}},{name:'open_design_screen',title:'Open a page design',description:'Navigate to an existing screen in the Sales Engine design prototype. Does not access live operations.',inputSchema:{type:'object',properties:{screenId:{type:'string',enum:SCREENS.map(s=>s.id)}},required:['screenId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.screenId!=='string'||!SCREEN[input.screenId]||Object.keys(input).some(k=>k!=='screenId'))throw Error('A valid screenId is required.');location.hash='/'+input.screenId;render();return {screenId:current,title:SCREEN[current].title,prototype:true};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}})();
